#!/usr/bin/env node
// Agentic Harness guard hook for Claude Code (PreToolUse). Generated by Agentic Harness; re-export instead of editing.
// Exit code 2 blocks the tool call and shows the reason to the agent.
import fs from 'node:fs';
import path from 'node:path';

const projectDir = process.env.CLAUDE_PROJECT_DIR || process.cwd();
const read = (p) => {
  try {
    return JSON.parse(fs.readFileSync(path.join(projectDir, p), 'utf8'));
  } catch {
    return null;
  }
};

const escape = (s) => s.replace(/[.+^${}()|[\]\\]/g, '\\$&');
function globToRegExp(glob) {
  let re = '';
  for (let i = 0; i < glob.length; i++) {
    const c = glob[i];
    if (c === '*') {
      if (glob[i + 1] === '*') {
        if (glob[i + 2] === '/') { re += '(?:.*/)?'; i += 2; } else { re += '.*'; i += 1; }
      } else re += '[^/]*';
    } else if (c === '?') re += '[^/]';
    else if (c === '!' && glob[i + 1] === '(') {
      const end = glob.indexOf(')', i);
      re += `(?!(?:${glob.slice(i + 2, end).split('|').map(escape).join('|')})(?:/|$))[^/]*`;
      i = end;
    } else if (c === '{') {
      const end = glob.indexOf('}', i);
      re += `(?:${glob.slice(i + 1, end).split(',').map(escape).join('|')})`;
      i = end;
    } else re += escape(c);
  }
  return new RegExp(`^${re}$`);
}
const matches = (globs, rel) => globs.some((g) => globToRegExp(g).test(rel));

function block(reason) {
  process.stderr.write(`Agentic Harness policy: ${reason}\n`);
  process.exit(2);
}

let input = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', (d) => (input += d));
process.stdin.on('end', () => {
  const policy = read('.harness/policy.json');
  if (!policy) process.exit(0);
  let event;
  try {
    event = JSON.parse(input);
  } catch {
    process.exit(0);
  }
  const tool = event.tool_name || '';
  const ti = event.tool_input || {};
  const state = read('.harness/state.json');
  const op = state && policy.operations[state.operation];
  const forbidden = [...policy.global.forbiddenPaths, ...(op?.forbiddenPaths ?? [])];
  const denylist = [...policy.global.commandDenylist, ...(op?.commandDenylist ?? [])];

  const toRel = (p) => {
    if (!p) return null;
    const abs = path.resolve(projectDir, p);
    const rel = path.relative(projectDir, abs).split(path.sep).join('/');
    if (rel.startsWith('..') || path.isAbsolute(rel)) block(`"${p}" is outside the project.`);
    return rel || '.';
  };

  if (tool === 'Bash') {
    const cmd = String(ti.command || '');
    for (const pattern of denylist) {
      if (new RegExp(pattern, 'i').test(cmd)) block(`command matches forbidden pattern /${pattern}/. The harness and humans own git, network and publishing.`);
    }
    if (/gates\.mjs\s+approve\b/.test(cmd)) block('only a human may record an approval. Stop and ask the user to approve.');
    if (op?.commandAllowlist?.length && !/^\s*node\s+\.harness\/gates\.mjs\s+(start|check)\b/.test(cmd)) {
      if (!op.commandAllowlist.some((p) => new RegExp(p, 'i').test(cmd))) block(`command is not allowlisted for operation "${state.operation}".`);
    }
    process.exit(0);
  }

  const target = ti.file_path || ti.notebook_path || ti.path || null;
  const rel = toRel(target);
  if (rel && rel !== '.' && matches(forbidden, rel)) block(`"${rel}" is a forbidden path (no read or write).`);

  const writes = ['Write', 'Edit', 'MultiEdit', 'NotebookEdit'].includes(tool);
  if (writes && rel) {
    if (rel === '.harness/state.json' || rel.startsWith('.harness/policy') || rel.startsWith('.harness/pipeline') || rel.endsWith('/status.json') || rel.endsWith('/decisions.md')) {
      block(`"${rel}" is harness-owned.`);
    }
    if (op) {
      const workDir = `.harness/work/${state.slug}`;
      const own = op.artifacts.map((a) => `${workDir}/${a}`);
      if (rel.startsWith('.harness/')) {
        if (!own.includes(rel)) block(`"${rel}" is not an artifact of operation "${state.operation}". Artifacts of other operations are immutable.`);
      } else if (!matches(op.writablePaths, rel)) {
        block(`"${rel}" is read-only during operation "${state.operation}". Writable: ${op.writablePaths.join(', ') || '(artifacts only)'}.`);
      }
    }
  }
  process.exit(0);
});
